package lsp2

import (
	"bytes"
	"crypto/ed25519"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"flag"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// Conformance vectors: spec/testvectors/vectors.json is generated by this
// file (go test ./internal/lsp2 -run TestVectors -update) and then verified
// against the reference implementation. Other languages consume the same file.

var update = flag.Bool("update", false, "rewrite spec/testvectors/vectors.json")

const vecIat = int64(1767225600) // 2026-01-01T00:00:00Z

type vecKey struct {
	Seed               string `json:"seed_b64url"`
	Public             string `json:"public_b64url"`
	JWK                JWK    `json:"jwk"`
	JKT                string `json:"jkt"`
	JWKThumbprintInput string `json:"jwk_thumbprint_input"`
}

type vecJWS struct {
	Name            string          `json:"name"`
	Kind            string          `json:"kind"`
	SignedBy        string          `json:"signed_by"`
	ProtectedHeader json.RawMessage `json:"protected_header"`
	HeaderB64       string          `json:"protected_b64url"`
	Payload         json.RawMessage `json:"payload"`
	PayloadB64      string          `json:"payload_b64url"`
	SigningInput    string          `json:"signing_input"`
	Signature       string          `json:"signature_b64url"`
	Compact         string          `json:"compact"`
	Expect          map[string]any  `json:"verify_with"`
}

type vecNeg struct {
	Name     string         `json:"name"`
	Kind     string         `json:"kind"`
	Compact  string         `json:"compact"`
	VerifyBy string         `json:"verify_with_key"`
	Expect   map[string]any `json:"verify_with"`
	Why      string         `json:"must_reject_because"`
}

type vecFrame struct {
	Name  string          `json:"name"`
	Frame json.RawMessage `json:"frame"`
	Why   string          `json:"must_reject_because,omitempty"`
}

type vectors struct {
	Description string              `json:"description"`
	Now         int64               `json:"now"`
	Keys        map[string]vecKey   `json:"keys"`
	Base64URL   []map[string]string `json:"base64url"`
	Ath         []map[string]string `json:"ath"`
	JWS         []vecJWS            `json:"jws"`
	Negative    []vecNeg            `json:"negative"`
	ValidFrames []vecFrame          `json:"valid_frames"`
	BadFrames   []vecFrame          `json:"invalid_frames"`
}

func vkey(label string) (ed25519.PrivateKey, vecKey) {
	seed := sha256.Sum256([]byte(label))
	k := ed25519.NewKeyFromSeed(seed[:])
	pub := k.Public().(ed25519.PublicKey)
	return k, vecKey{Seed: B64(seed[:]), Public: B64(pub), JWK: PublicJWK(pub), JKT: Thumbprint(pub),
		JWKThumbprintInput: `{"crv":"Ed25519","kty":"OKP","x":"` + B64(pub) + `"}`}
}

func mkJWS(name, kind, by string, key ed25519.PrivateKey, typ, kid string, payload any, expect map[string]any) vecJWS {
	p, _ := json.Marshal(payload)
	c := SignJWS(key, typ, kid, p)
	parts := strings.Split(c, ".")
	h, _ := UnB64(parts[0])
	return vecJWS{Name: name, Kind: kind, SignedBy: by, ProtectedHeader: h, HeaderB64: parts[0], Payload: p, PayloadB64: parts[1],
		SigningInput: parts[0] + "." + parts[1], Signature: parts[2], Compact: c, Expect: expect}
}

func rawJWS(key ed25519.PrivateKey, header string, payload []byte) string {
	in := B64([]byte(header)) + "." + B64(payload)
	return in + "." + B64(ed25519.Sign(key, []byte(in)))
}

func generate() vectors {
	dk, dv := vkey("lsp2 test vector: device key")
	gk, gv := vkey("lsp2 test vector: gateway key")
	devID := "dev_0192f5e0-7c1a-7cc0-9b4a-3f1d2e5a6b70"
	kid := gv.JKT
	at := Claims{Iss: "lsp2-gateway", Sub: devID, Aud: "lsp2-gateway", Tenant: "acme", Iat: vecIat, Exp: vecIat + 600, Jti: "jti_0192f5e0-7c1a-7cc0-9b4a-000000000001", Cnf: map[string]string{"jkt": dv.JKT}}
	atJWS := mkJWS("access_token", "access_token", "gateway", gk, TypAccessToken, kid, at, map[string]any{"typ": TypAccessToken, "aud": "lsp2-gateway", "cnf.jkt": dv.JKT})
	as := Claims{Iss: devID, Sub: devID, Aud: "lsp2-gateway/token", Iat: vecIat, Exp: vecIat + 60, Jti: "a_0192f5e0-7c1a-7cc0-9b4a-000000000002"}
	asJWS := mkJWS("client_assertion", "client_assertion", "device", dk, TypAssertion, dv.JKT, as, map[string]any{"typ": TypAssertion, "aud": "lsp2-gateway/token"})
	deviceCode := "dc_0192f5e0-7c1a-7cc0-9b4a-000000000003"
	pTok := ProofClaims{Iss: "", Aud: ProofToken, Iat: vecIat, Jti: "p_0192f5e0-7c1a-7cc0-9b4a-000000000004", Ath: Ath(deviceCode)}
	pHello := ProofClaims{Iss: devID, Aud: ProofHello, Iat: vecIat, Jti: "p_0192f5e0-7c1a-7cc0-9b4a-000000000005", Ath: Ath(atJWS.Compact)}
	pSess := ProofClaims{Iss: devID, Aud: ProofSessionToken, Iat: vecIat, Jti: "p_0192f5e0-7c1a-7cc0-9b4a-000000000006", Ath: Ath(atJWS.Compact)}
	temp := 0.7
	run := TaskRun{TaskID: "task_0192f5e0-7c1a-7cc0-9b4a-000000000007", Iat: vecIat, DeviceID: devID, Model: "lm/qwen3-8b",
		Messages:  []Message{{Role: "system", Content: "你是助手"}, {Role: "user", Content: "Hello, 世界 👋 \"quoted\" \\ </script>"}},
		MaxTokens: 256, Temperature: &temp, Exp: vecIat + 60, Nonce: "n_9f86d081884c7d659a2feaa0c55ad015"}
	runJWS := mkJWS("task_run", "task_run", "gateway", gk, TypTask, kid, run, map[string]any{"typ": TypTask, "envelope_task_id": run.TaskID})
	v := vectors{
		Description: "lsp2 conformance vectors. Keys are derived as SHA-256(label) used as Ed25519 seed. 'now' is the verification time (NumericDate). Implementations MUST verify every jws entry with the listed key/expectations and MUST reject every negative entry. Signers are not required to reproduce payload bytes exactly, but Ed25519 over signing_input with the given key MUST yield signature_b64url (Ed25519 is deterministic).",
		Now:         vecIat + 10,
		Keys:        map[string]vecKey{"device": dv, "gateway": gv},
		Base64URL: []map[string]string{
			{"bytes_hex": "", "b64url": ""}, {"bytes_hex": "ff", "b64url": "_w"}, {"bytes_hex": "fbff", "b64url": "-_8"}, {"bytes_hex": "000102", "b64url": "AAEC"},
			{"bytes_hex": hex.EncodeToString([]byte("lsp2")), "b64url": B64([]byte("lsp2"))},
		},
		Ath: []map[string]string{{"credential": deviceCode, "ath": Ath(deviceCode)}, {"credential": atJWS.Compact, "ath": Ath(atJWS.Compact)}},
		JWS: []vecJWS{atJWS, asJWS,
			mkJWS("proof_token_grant", "proof", "device", dk, TypProof, "", pTok, map[string]any{"aud": ProofToken, "iss": "", "credential": deviceCode}),
			mkJWS("proof_hello", "proof", "device", dk, TypProof, "", pHello, map[string]any{"aud": ProofHello, "iss": devID, "credential": atJWS.Compact}),
			mkJWS("proof_session_token", "proof", "device", dk, TypProof, "", pSess, map[string]any{"aud": ProofSessionToken, "iss": devID, "credential": atJWS.Compact}),
			runJWS,
		},
	}
	atPayload, _ := json.Marshal(at)
	tampered := strings.Split(atJWS.Compact, ".")
	evil := at
	evil.Sub = "dev_attacker"
	ep, _ := json.Marshal(evil)
	hello := map[string]any{"aud": ProofHello, "iss": devID, "credential": atJWS.Compact}
	stale := pHello
	stale.Iat = vecIat - 300
	expired := at
	expired.Exp = vecIat - 100
	expired.Iat = vecIat - 700
	v.Negative = []vecNeg{
		{"alg_none", "access_token", B64([]byte(`{"alg":"none","typ":"at+jwt"}`)) + "." + B64(atPayload) + ".", "gateway", atJWS.Expect, "alg must be EdDSA"},
		{"alg_hs256", "access_token", rawJWS(gk, `{"alg":"HS256","typ":"at+jwt"}`, atPayload), "gateway", atJWS.Expect, "alg must be EdDSA"},
		{"tampered_payload", "access_token", tampered[0] + "." + B64(ep) + "." + tampered[2], "gateway", atJWS.Expect, "signature does not cover payload"},
		{"wrong_key", "access_token", SignJWS(dk, TypAccessToken, kid, atPayload), "gateway", atJWS.Expect, "signed by device key, not gateway key"},
		{"padded_base64url", "access_token", atJWS.Compact + "==", "gateway", atJWS.Expect, "base64url padding is forbidden"},
		{"crit_header", "access_token", rawJWS(gk, `{"alg":"EdDSA","crit":["exp"],"exp":1,"typ":"at+jwt"}`, atPayload), "gateway", atJWS.Expect, "unknown crit parameter"},
		{"expired_access_token", "access_token", mkJWS("", "", "", gk, TypAccessToken, kid, expired, nil).Compact, "gateway", atJWS.Expect, "exp + 30s leeway < now"},
		{"proof_as_access_token", "access_token", v.JWS[3].Compact, "device", atJWS.Expect, "typ lsp2-proof+jwt is not at+jwt (explicit typing)"},
		{"access_token_as_task", "task_run", atJWS.Compact, "gateway", runJWS.Expect, "typ at+jwt is not lsp2-task+jws"},
		{"task_id_mismatch", "task_run", runJWS.Compact, "gateway", map[string]any{"typ": TypTask, "envelope_task_id": "task_other"}, "payload task_id differs from envelope task_id"},
		{"proof_wrong_ath", "proof", v.JWS[3].Compact, "device", map[string]any{"aud": ProofHello, "iss": devID, "credential": "another-token"}, "ath does not match the presented access token"},
		{"proof_wrong_aud", "proof", v.JWS[3].Compact, "device", map[string]any{"aud": ProofSessionToken, "iss": devID, "credential": atJWS.Compact}, "proof minted for hello replayed as session.token"},
		{"proof_stale", "proof", mkJWS("", "", "", dk, TypProof, "", stale, nil).Compact, "device", hello, "|iat - now| > 60s"},
	}
	frames := []any{
		map[string]any{"v": 2, "type": "hello", "id": "h1", "data": map[string]any{"device_id": devID, "client": "example/1.0", "models": []string{"lm/qwen3-8b"}, "max_concurrency": 1, "capabilities": Capabilities, "proof": v.JWS[3].Compact}},
		map[string]any{"v": 2, "type": "welcome", "id": "h1", "data": map[string]any{"session_id": "sess_01", "heartbeat_seconds": 20, "max_frame_bytes": 1 << 20, "token_expires_at": vecIat + 600, "capabilities": Capabilities}},
		map[string]any{"v": 2, "type": "task.run", "task_id": run.TaskID, "jws": runJWS.Compact},
		map[string]any{"v": 2, "type": "task.delta", "task_id": run.TaskID, "seq": 1, "data": map[string]any{"text": "你好"}},
		map[string]any{"v": 2, "type": "task.done", "task_id": run.TaskID, "seq": 2, "data": map[string]any{"finish_reason": "stop", "usage": map[string]any{"prompt_tokens": 7, "completion_tokens": 2}}},
		map[string]any{"v": 2, "type": "task.error", "task_id": run.TaskID, "seq": 1, "data": map[string]any{"code": "UPSTREAM_ERROR", "message": "model crashed", "retryable": false}},
		map[string]any{"v": 2, "type": "task.cancel", "task_id": run.TaskID, "data": map[string]any{"reason": "client_disconnected"}},
		map[string]any{"v": 2, "type": "ping", "id": "p1"},
		map[string]any{"v": 2, "type": "pong", "id": "p1"},
		map[string]any{"v": 2, "type": "session.token", "id": "t1", "data": map[string]any{"access_token": atJWS.Compact, "proof": v.JWS[4].Compact}},
		map[string]any{"v": 2, "type": "session.token", "id": "t1", "data": map[string]any{"token_expires_at": vecIat + 1200}},
		map[string]any{"v": 2, "type": "models.update", "data": map[string]any{"models": []string{"lm/qwen3-8b", "codex/gpt-5"}, "max_concurrency": 1}},
		map[string]any{"v": 2, "type": "error", "id": "h1", "data": map[string]any{"code": "UNAUTHENTICATED", "message": "invalid key proof"}},
		map[string]any{"v": 2, "type": "x.vendor.future", "id": "f1", "data": map[string]any{"anything": true}, "unknown_member": 1},
	}
	names := []string{"hello", "welcome", "task.run", "task.delta", "task.done", "task.error", "task.cancel", "ping", "pong", "session.token(request)", "session.token(response)", "models.update", "error", "unknown type (receivers ignore or answer error, never crash)"}
	for i, f := range frames {
		b, _ := json.Marshal(f)
		v.ValidFrames = append(v.ValidFrames, vecFrame{Name: names[i], Frame: b})
	}
	bad := []struct{ n, why, f string }{
		{"wrong_version", "v must be 2", `{"v":1,"type":"ping"}`},
		{"missing_type", "type is required", `{"v":2}`},
		{"task_run_with_data", "task.run payload must only travel inside jws", `{"v":2,"type":"task.run","task_id":"t1","jws":"` + runJWS.Compact + `","data":{"model":"x"}}`},
		{"delta_without_seq", "task.delta requires seq", `{"v":2,"type":"task.delta","task_id":"t1","data":{"text":"a"}}`},
		{"seq_zero", "seq starts at 1", `{"v":2,"type":"task.delta","task_id":"t1","seq":0,"data":{"text":"a"}}`},
		{"hello_without_proof", "hello requires proof", `{"v":2,"type":"hello","id":"h1","data":{"device_id":"d","client":"c","models":[],"max_concurrency":1}}`},
		{"bad_error_code", "error codes are UPPER_SNAKE", `{"v":2,"type":"error","data":{"code":"oops","message":"x"}}`},
		{"concurrency_out_of_range", "max_concurrency is 1..16", `{"v":2,"type":"models.update","data":{"models":[],"max_concurrency":100}}`},
	}
	for _, b := range bad {
		v.BadFrames = append(v.BadFrames, vecFrame{Name: b.n, Frame: json.RawMessage(b.f), Why: b.why})
	}
	return v
}

func vecPath() string { return filepath.Join("..", "..", "spec", "testvectors", "vectors.json") }

func marshalVectors(v vectors) []byte {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	_ = enc.Encode(v)
	return buf.Bytes()
}

func TestVectors(t *testing.T) {
	want := marshalVectors(generate())
	if *update {
		if err := os.WriteFile(vecPath(), want, 0o644); err != nil {
			t.Fatal(err)
		}
	}
	got, err := os.ReadFile(vecPath())
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(got, want) {
		t.Fatal("spec/testvectors/vectors.json is stale; run go test ./internal/lsp2 -run TestVectors -update")
	}
	var v vectors
	if err := json.Unmarshal(got, &v); err != nil {
		t.Fatal(err)
	}
	now := time.Unix(v.Now, 0)
	keyOf := func(n string) ed25519.PublicKey { b, _ := UnB64(v.Keys[n].Public); return b }
	for _, k := range v.Keys {
		seed, _ := UnB64(k.Seed)
		pub := ed25519.NewKeyFromSeed(seed).Public().(ed25519.PublicKey)
		if B64(pub) != k.Public || Thumbprint(pub) != k.JKT {
			t.Fatal("key/thumbprint mismatch")
		}
	}
	for _, c := range v.Base64URL {
		b, _ := hex.DecodeString(c["bytes_hex"])
		if B64(b) != c["b64url"] {
			t.Fatalf("base64url %v", c)
		}
	}
	check := func(kind, compact string, pub ed25519.PublicKey, exp map[string]any) error {
		s := func(k string) string { x, _ := exp[k].(string); return x }
		switch kind {
		case "access_token":
			c, err := VerifyJWT(pub, compact, TypAccessToken, s("aud"), now)
			if err == nil && c.Cnf["jkt"] != s("cnf.jkt") {
				return os.ErrInvalid
			}
			return err
		case "client_assertion":
			_, err := VerifyJWT(pub, compact, TypAssertion, s("aud"), now)
			return err
		case "proof":
			_, err := VerifyProof(pub, compact, s("iss"), s("aud"), s("credential"), now)
			return err
		case "task_run":
			_, err := VerifyTaskRun(pub, s("envelope_task_id"), compact)
			return err
		}
		return os.ErrInvalid
	}
	for _, j := range v.JWS {
		seed, _ := UnB64(v.Keys[j.SignedBy].Seed)
		sig := ed25519.Sign(ed25519.NewKeyFromSeed(seed), []byte(j.SigningInput))
		if B64(sig) != j.Signature || j.SigningInput+"."+j.Signature != j.Compact {
			t.Fatalf("%s: signature not reproducible", j.Name)
		}
		if err := check(j.Kind, j.Compact, keyOf(j.SignedBy), j.Expect); err != nil {
			t.Fatalf("%s: %v", j.Name, err)
		}
	}
	for _, n := range v.Negative {
		if check(n.Kind, n.Compact, keyOf(n.VerifyBy), n.Expect) == nil {
			t.Fatalf("negative vector %s accepted", n.Name)
		}
	}
}
